`timescale 1 ns / 1 ns

module Sample_and_Hold_block
          (clk,
           reset,
           enb,
           In_rsvd,
           Trigger_rsvd,
           alpha);


  input   clk;
  input   reset;
  input   enb;
  input   [15:0] In_rsvd;  // ufix16_En7
  input   Trigger_rsvd;
  output  [15:0] alpha;  // ufix16_En7


  wire enb_gated;
  reg  Trigger_delayed;
  wire Trigger_emulated;
  wire [15:0] In_bypass;  // ufix16_En7
  reg [15:0] In_last_value;  // ufix16_En7


  always @(posedge clk)
    begin : Trigger_delay
      if (reset) begin
        Trigger_delayed <= 1'b1;
      end
      else begin
        if (enb) begin
          Trigger_delayed <= Trigger_rsvd;
        end
      end
    end

  assign Trigger_emulated = !Trigger_delayed && Trigger_rsvd;

  assign enb_gated = Trigger_emulated && enb;

  always @(posedge clk)
    begin : alpha_bypass_process
      if (reset == 1'b1) begin
        In_last_value <= 16'b0000000000000000;
      end
      else begin
        if (enb_gated) begin
          In_last_value <= In_bypass;
        end
      end
    end



  assign In_bypass = (Trigger_emulated == 1'b0 ? In_last_value :
              In_rsvd);



  assign alpha = In_bypass;

endmodule  // Sample_and_Hold_block

